package com.stockflow.inventory;
import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.nio.charset.StandardCharsets; import java.security.MessageDigest; import java.util.*;
@Service @RequiredArgsConstructor public class InventoryService { private final StockBalanceRepository balances; private final InventoryMovementRepository movements; private final InventoryMovementLineRepository lines; private final IdempotencyRepository idem;
 @Transactional public UUID post(String key,MovementType type,StockCommand c){String hash=hash(type+c.toString()); var old=idem.findByCompanyIdAndKey(c.companyId(),key); if(old.isPresent()){if(!old.get().getRequestHash().equals(hash))throw new IllegalStateException("IDEMPOTENCY_KEY_REUSED");return old.get().getResponseId();} String lot=c.lotKey()==null?"-":c.lotKey(); var b=balances.lock(c.companyId(),c.locationId(),c.variantId(),lot).orElseGet(()->new StockBalance(c.companyId(),c.locationId(),c.variantId(),lot)); if(type==MovementType.RECEIPT||type==MovementType.CUSTOMER_RETURN||type==MovementType.TRANSFER_IN)b.receive(c.quantity()); else b.issue(c.quantity()); balances.save(b); var m=movements.save(new InventoryMovement(c.companyId(),type,"DOCUMENT",c.documentId(),c.actorId())); lines.save(new InventoryMovementLine(m.getId(),c.variantId(),c.locationId(),c.quantity(),c.unitCost(),lot)); idem.save(new IdempotencyRecord(c.companyId(),key,hash,m.getId())); return m.getId(); }
 private String hash(String s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
}
